--> statement-breakpoint
WITH src AS (
  SELECT g."id", substring(g."body" from E'```gear\n(.*?)\n```')::jsonb AS j
  FROM "guides" g
  WHERE g."clan_id" IS NULL AND g."body" LIKE '%```gear%' AND g."slug" <> 'vorkath-guide'
    AND g."body" NOT LIKE '%"setups":[{"id":%'
), conv AS (
  SELECT src."id", jsonb_set(src.j, '{setups}', COALESCE((
    SELECT jsonb_agg(
      s.v
      || jsonb_build_object('id', (s.v->>'tier') || '-' || COALESCE(NULLIF(left(trim(both '-' from regexp_replace(lower(COALESCE(s.v->>'name', 'setup')), '[^a-z0-9]+', '-', 'g')), 32), ''), 'setup') || '-' || (s.n - 1))
      || CASE WHEN s.v ? 'spell' AND COALESCE(s.v->>'spell', '') <> '' THEN jsonb_build_object('spells', jsonb_build_array(s.v->>'spell')) ELSE '{}'::jsonb END
      ORDER BY s.n)
    FROM jsonb_array_elements(src.j->'setups') WITH ORDINALITY AS s(v, n)
  ), '[]'::jsonb)) AS j
  FROM src
), lib AS (
  UPDATE "guides" g SET "body" = regexp_replace(g."body", E'```gear\n.*?\n```', E'```gear\n' || replace(conv.j::text, '\', '\\') || E'\n```'), "version" = g."version" + 1, "updated_at" = to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
  FROM conv WHERE g."id" = conv."id"
  RETURNING g."id", g."version", g."title", g."summary", g."body"
), lib_rev AS (
  INSERT INTO "guide_revisions" ("guide_id","version","title","summary","body","note","created_at")
  SELECT "id","version","title","summary","body",'Setups now carry stable ids and their spells',to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') FROM lib
), copies AS (
  UPDATE "guides" g SET "body" = lib."body", "version" = g."version" + 1, "source_version" = lib."version", "updated_at" = to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
  FROM lib WHERE g."source_guide_id" = lib."id" AND g."follows_source" = true
  RETURNING g."id", g."version", g."title", g."summary", g."body"
)
INSERT INTO "guide_revisions" ("guide_id","version","title","summary","body","note","created_at")
SELECT "id","version","title","summary","body",'Synced with the Anvil library',to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') FROM copies ON CONFLICT DO NOTHING;
